-- Level Up meal catalogue: 12 complete editorial recipes + 300 source-index drafts.
-- Published nutrition and representative imagery are explicitly unverified.
-- Keep these records separate from users' meals and food logs.
CREATE TABLE IF NOT EXISTS meal_recipe_catalogue (
 recipe_id TEXT PRIMARY KEY,
 name TEXT NOT NULL,
 meal_slot TEXT NOT NULL,
 source_name TEXT,
 source_url TEXT,
 source_index_url TEXT,
 servings INTEGER,
 ingredients_json TEXT NOT NULL DEFAULT '[]',
 instructions_json TEXT NOT NULL DEFAULT '[]',
 publisher_nutrition_json TEXT,
 image_asset TEXT,
 image_tile INTEGER,
 image_columns INTEGER,
 image_rows INTEGER,
 image_status TEXT NOT NULL DEFAULT 'missing',
 content_status TEXT NOT NULL DEFAULT 'source_index_only',
 can_schedule INTEGER NOT NULL DEFAULT 0 CHECK(can_schedule IN (0,1)),
 updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_meal_recipe_catalogue_status ON meal_recipe_catalogue(content_status, meal_slot);
