INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('cilantro-lime-chicken','Creamy Cilantro Lime Chicken Bowls','Lunch','Level Up original adaptation','https://mealprepmanual.com/creamy-cilantro-lime-chicken-bowls/',NULL,5,'[["Chicken thighs (raw)",181.6,"g","Protein"],["White rice (cooked)",90,"g","Grains"],["Sweet potato",68,"g","Produce"],["Broccoli",45.4,"g","Produce"],["Plain Greek yogurt (2%)",24,"g","Dairy"],["Cilantro",4,"g","Produce"],["Green onions",4,"g","Produce"],["Jalapeño",4,"g","Produce"],["Lime juice",9,"mL","Produce"],["Water",6,"mL","Other"],["Cooking oil",9,"g","Seasoning"],["Smoked paprika",1.2,"g","Seasoning"],["Garlic powder",1.8,"g","Seasoning"],["Onion powder",0.6,"g","Seasoning"],["Chili powder",0.6,"g","Seasoning"],["Ground cumin",0.2,"g","Seasoning"],["Salt",2,"g","Seasoning"],["Black pepper",0.6,"g","Seasoning"]]','["Cook the rice and spread it out briefly so it is ready to portion.","Season chicken thighs with paprika, garlic and onion powders, chili powder, salt, pepper, lime and a little oil. Roast at 204°C until the centres reach 74°C.","Cut sweet potato into small cubes. Roast with oil; add small broccoli florets partway through so both vegetables finish tender.","Blend yogurt, cilantro, green onion, jalapeño, cumin, lime juice and water into a smooth pourable dressing.","Slice the cooked chicken and divide it with rice and vegetables among five containers. Package the dressing separately until serving."]','{"calories":490,"protein":43,"carbs":46,"fat":15,"fiber":4.8}','/assets/meal-photos/featured8-hq.avif',0,4,2,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('korean-beef','Sesame Korean Beef Rice Bowls','Lunch','Level Up original adaptation',NULL,NULL,4,'[["Lean ground beef",170,"g","Protein"],["White rice (dry)",70,"g","Grains"],["Cucumber",75,"g","Produce"],["Carrot",60,"g","Produce"],["Green onions",20,"g","Produce"],["Soy sauce",15,"mL","Condiments"],["Honey",10,"g","Condiments"],["Garlic",5,"g","Produce"],["Ginger",4,"g","Produce"],["Sesame oil",5,"g","Seasoning"],["Sesame seeds",5,"g","Seasoning"],["Chili flakes",0.5,"g","Seasoning"]]','["Rinse rice, then cook it according to its package directions.","Mix soy sauce, honey, grated ginger, minced garlic, sesame oil and chili flakes in a small bowl.","Brown the lean ground beef in a skillet over medium heat, breaking it into small pieces; cook thoroughly to 71°C.","Stir the sauce into the beef and simmer until it lightly coats the meat.","Slice cucumber, shred carrot and chop green onions. Divide cooked rice and beef among containers; keep fresh vegetables separate until serving and sprinkle with sesame seeds."]',NULL,'/assets/meal-photos/featured8-hq.avif',2,4,2,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('teriyaki-chicken','Teriyaki Chicken & Vegetable Rice Bowls','Lunch','Level Up original adaptation',NULL,NULL,4,'[["Chicken breast (raw)",180,"g","Protein"],["White rice (dry)",70,"g","Grains"],["Broccoli",100,"g","Produce"],["Bell pepper",80,"g","Produce"],["Carrot",60,"g","Produce"],["Soy sauce",15,"mL","Condiments"],["Honey",12,"g","Condiments"],["Rice vinegar",8,"mL","Condiments"],["Garlic",4,"g","Produce"],["Ginger",4,"g","Produce"],["Cornstarch",4,"g","Grains"],["Sesame oil",5,"g","Seasoning"]]','["Cook the rice following package directions.","Whisk soy sauce, honey, rice vinegar, ginger and garlic together. Dissolve the cornstarch in a little cold water separately.","Cut chicken into bite-size pieces and cook in sesame oil over medium-high heat until it reaches 74°C.","Steam or sauté broccoli, carrots and bell pepper until tender-crisp.","Add sauce and cornstarch slurry to the chicken; simmer until thickened. Pack chicken, vegetables and rice into containers."]',NULL,'/assets/meal-photos/featured8-hq.avif',1,4,2,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('med-chicken-wrap','Mediterranean Chicken & Feta Wraps','Lunch','Level Up original adaptation',NULL,NULL,4,'[["Chicken breast (raw)",170,"g","Protein"],["Whole-wheat tortilla",75,"g","Grains"],["Cucumber",60,"g","Produce"],["Tomatoes",70,"g","Produce"],["Romaine lettuce",35,"g","Produce"],["Red onion",20,"g","Produce"],["Feta",30,"g","Dairy"],["Plain Greek yogurt",45,"g","Dairy"],["Lemon juice",10,"mL","Produce"],["Garlic",3,"g","Produce"],["Olive oil",5,"g","Seasoning"],["Dried oregano",1,"g","Seasoning"]]','["Season chicken with oregano, garlic and olive oil. Cook until the thickest part reaches 74°C, then rest and slice.","Mix plain Greek yogurt with lemon juice and a little minced garlic for a tangy sauce.","Wash and chop lettuce, cucumber, tomatoes and red onion; crumble the feta.","Lay out tortillas and distribute the sliced chicken, vegetables and feta evenly.","Keep the yogurt sauce separate if making ahead; add it just before rolling the wraps to prevent sogginess."]',NULL,'/assets/meal-photos/featured8-hq.avif',6,4,2,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('taco-mac','Cheesy Taco Beef Macaroni','Lunch','Level Up original adaptation',NULL,NULL,5,'[["Lean ground beef",160,"g","Protein"],["Dry macaroni",80,"g","Grains"],["Canned crushed tomatoes",100,"g","Canned"],["Cheddar cheese",30,"g","Dairy"],["Onion",40,"g","Produce"],["Bell pepper",60,"g","Produce"],["Garlic",4,"g","Produce"],["Tomato paste",20,"g","Canned"],["Chili powder",2,"g","Seasoning"],["Ground cumin",1,"g","Seasoning"],["Smoked paprika",1,"g","Seasoning"]]','["Boil macaroni in lightly salted water until just tender, then drain, reserving a little cooking water.","Cook ground beef in a large skillet until browned and fully cooked to 71°C.","Add diced onion and pepper; cook until softened. Stir in minced garlic, chili powder, cumin and smoked paprika.","Stir in tomato paste and crushed tomatoes, then simmer for several minutes. Loosen with a splash of reserved pasta water if needed.","Fold macaroni into the beef sauce and top with grated cheddar. Divide into meal-prep containers once cooled slightly."]',NULL,'/assets/meal-photos/generated-001-020.png',12,5,4,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('turkey-chili','Smoky Turkey & Sweet Potato Chili','Lunch','Level Up original adaptation',NULL,NULL,5,'[["Lean ground turkey",180,"g","Protein"],["Sweet potato",150,"g","Produce"],["Kidney beans (drained)",110,"g","Canned"],["Canned crushed tomatoes",140,"g","Canned"],["Onion",50,"g","Produce"],["Bell pepper",70,"g","Produce"],["Garlic",5,"g","Produce"],["Olive oil",5,"g","Seasoning"],["Chili powder",2,"g","Seasoning"],["Ground cumin",1.5,"g","Seasoning"],["Smoked paprika",1,"g","Seasoning"]]','["Dice sweet potato, onion and bell pepper into small, even pieces; mince the garlic.","Warm olive oil in a heavy pot, then brown ground turkey until cooked through to 74°C.","Add onion, pepper and garlic; cook until fragrant, then stir in chili powder, cumin and smoked paprika.","Add sweet potato cubes, drained kidney beans and crushed tomatoes, plus water as needed. Simmer until the sweet potato is tender.","Taste and adjust seasoning; divide into containers. Freeze portions that will not be eaten within 2–3 days."]',NULL,'/assets/meal-photos/generated-001-020.png',15,5,4,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('breakfast-burrito','Egg, Turkey Sausage & Potato Breakfast Wrap','Breakfast','Level Up original adaptation',NULL,NULL,4,'[["Eggs",110,"g","Protein"],["Turkey sausage",90,"g","Protein"],["Potatoes",130,"g","Produce"],["Whole-wheat tortilla",75,"g","Grains"],["Cheddar cheese",20,"g","Dairy"],["Bell pepper",40,"g","Produce"],["Onion",25,"g","Produce"],["Olive oil",5,"g","Seasoning"],["Smoked paprika",0.5,"g","Seasoning"]]','["Dice potatoes and cook them in a little olive oil with smoked paprika until tender and lightly browned.","Cook turkey sausage according to its package instructions, ensuring poultry sausage reaches 74°C.","Sauté the pepper and onion. Beat eggs, then scramble gently until completely set.","Warm the tortillas briefly, then layer potato, sausage, vegetables, scrambled egg and grated cheddar.","Roll tightly, let fillings cool before wrapping for storage, and freeze later servings. Reheat until piping hot, ideally 74°C."]',NULL,'/assets/meal-photos/generated-001-020.png',5,5,4,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('protein-oats','Banana Cinnamon Baked Protein Oats','Breakfast','Level Up original adaptation',NULL,NULL,6,'[["Rolled oats",70,"g","Grains"],["Banana",95,"g","Produce"],["Milk",130,"mL","Dairy"],["Plain Greek yogurt",100,"g","Dairy"],["Egg",55,"g","Protein"],["Peanut butter",15,"g","Condiments"],["Baking powder",3,"g","Seasoning"],["Ground cinnamon",1,"g","Seasoning"]]','["Preheat the oven to 180°C and lightly grease an appropriately sized baking dish.","Mash banana and whisk it with milk, Greek yogurt, egg and peanut butter until combined.","Mix in rolled oats, baking powder and cinnamon; rest for a few minutes so the oats absorb some liquid.","Spread mixture into the baking dish and bake until the centre is set and no wet batter remains, about 25–35 minutes depending on the pan.","Cool, slice into six portions and refrigerate. Reheat with a splash of milk if desired."]',NULL,'/assets/meal-photos/generated-001-020.png',0,5,4,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('peanut-noodles','Ginger Peanut Chicken Noodles','Lunch','Level Up original adaptation',NULL,NULL,4,'[["Chicken breast (raw)",170,"g","Protein"],["Dry rice noodles",75,"g","Grains"],["Carrot",70,"g","Produce"],["Red cabbage",70,"g","Produce"],["Green onions",20,"g","Produce"],["Peanut butter",22,"g","Condiments"],["Soy sauce",15,"mL","Condiments"],["Lime juice",10,"mL","Produce"],["Ginger",5,"g","Produce"],["Garlic",4,"g","Produce"],["Honey",7,"g","Condiments"]]','["Cook rice noodles according to the package instructions, rinse briefly and drain.","Whisk peanut butter with soy sauce, lime juice, honey, grated ginger and minced garlic. Add warm water a little at a time to make a pourable sauce.","Cook sliced chicken breast until it reaches 74°C; cut into thin strips.","Thinly slice the carrot and red cabbage, and chop green onions.","Toss noodles and chicken with sauce. Add vegetables and green onions; pack cold vegetables separately if planning to reheat the chicken noodles."]',NULL,'/assets/meal-photos/featured8-hq.avif',7,4,2,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('med-chickpea','Lemon Herb Chickpea & Quinoa Bowls','Lunch','Level Up original adaptation',NULL,NULL,4,'[["Chickpeas (drained)",170,"g","Canned"],["Quinoa (dry)",65,"g","Grains"],["Cucumber",80,"g","Produce"],["Tomatoes",85,"g","Produce"],["Spinach",50,"g","Produce"],["Feta",35,"g","Dairy"],["Plain Greek yogurt",60,"g","Dairy"],["Lemon juice",15,"mL","Produce"],["Olive oil",8,"g","Seasoning"],["Dried oregano",1,"g","Seasoning"]]','["Rinse quinoa and cook according to package instructions, then fluff and cool.","Drain and rinse chickpeas. Toss them with a little olive oil and dried oregano.","Chop cucumber and tomatoes; wash and dry spinach.","Combine yogurt and lemon juice to make a light dressing. Crumble feta.","Portion quinoa, chickpeas, spinach, cucumber, tomatoes and feta into bowls; store yogurt dressing separately until eating."]',NULL,'/assets/meal-photos/generated-001-020.png',8,5,4,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('bbq-burger-bowl','BBQ Cheddar Burger & Potato Bowls','Lunch','Level Up original adaptation',NULL,NULL,4,'[["Lean ground beef",175,"g","Protein"],["Potatoes",220,"g","Produce"],["Cheddar cheese",30,"g","Dairy"],["Romaine lettuce",50,"g","Produce"],["Tomatoes",70,"g","Produce"],["Pickles",35,"g","Produce"],["Red onion",25,"g","Produce"],["BBQ sauce",25,"g","Condiments"],["Plain Greek yogurt",30,"g","Dairy"],["Smoked paprika",1,"g","Seasoning"]]','["Preheat the oven to 220°C. Dice potatoes into bite-size pieces and roast, turning once, until golden and tender.","Brown ground beef in a skillet until it reaches 71°C; season with smoked paprika.","Chop lettuce, tomato, pickles and red onion.","Mix Greek yogurt with a little BBQ sauce to make a creamy dressing; keep remaining sauce for the beef.","Portion potatoes and beef into heat-safe containers, then top with cheddar. Pack lettuce and fresh toppings separately to add after reheating."]',NULL,'/assets/meal-photos/generated-001-020.png',13,5,4,'representative-generated','ingredient_complete_unverified',1);
INSERT OR IGNORE INTO meal_recipe_catalogue (recipe_id,name,meal_slot,source_name,source_url,source_index_url,servings,ingredients_json,instructions_json,publisher_nutrition_json,image_asset,image_tile,image_columns,image_rows,image_status,content_status,can_schedule) VALUES ('chicken-curry','Tomato Coconut Chicken Curry & Rice','Lunch','Level Up original adaptation',NULL,NULL,5,'[["Chicken breast (raw)",180,"g","Protein"],["White rice (dry)",75,"g","Grains"],["Light coconut milk",100,"mL","Canned"],["Canned crushed tomatoes",100,"g","Canned"],["Spinach",70,"g","Produce"],["Onion",55,"g","Produce"],["Garlic",5,"g","Produce"],["Ginger",5,"g","Produce"],["Curry powder",3,"g","Seasoning"],["Olive oil",5,"g","Seasoning"]]','["Cook white rice according to the package directions.","Dice chicken and cook in olive oil until lightly golden; continue cooking thoroughly to 74°C.","Add chopped onion, garlic, ginger and curry powder; cook briefly until fragrant.","Pour in crushed tomatoes and coconut milk, then simmer gently until the sauce thickens and chicken is fully cooked.","Stir in spinach until wilted. Divide curry and rice among containers, keeping portions intended for later in the freezer."]',NULL,'/assets/meal-photos/featured8-hq.avif',4,4,2,'representative-generated','ingredient_complete_unverified',1);
